$$ SELECT $1 = auth.uid() OR public.hrms_is_admin_user(auth.uid())
       OR EXISTS (SELECT 1 FROM public.user_permissions up
                  WHERE up.user_id = auth.uid() AND up.permission = $2 AND up.revoked_at IS NULL) $$;
