$$ SELECT jsonb_build_object('kind', CASE WHEN EXTRACT(dow FROM p_date)::int = coalesce(p.weekly_off_day, 0)
                                        THEN 'WEEKLY_OFF' ELSE 'WORKING_DAY' END)
   FROM public.profiles p WHERE p.id = p_user_id $$;
