-- Test helper: stops the run on the first wrong result.
CREATE FUNCTION public.t_assert(label text, actual text, expected text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF actual IS DISTINCT FROM expected THEN
    RAISE EXCEPTION 'FAIL %: expected [%] got [%]', label, expected, actual;
  END IF;
  RAISE NOTICE 'ok  %', label;
END $$;
