-- from supabase/migrations/20260720000000_current_location_fallback.sql
create or replace function public.field_visit_distance_metres(lat1 double precision, lon1 double precision, lat2 double precision, lon2 double precision)
returns double precision language sql immutable strict parallel safe as $$
  select 6371000 * 2 * asin(sqrt(
    power(sin(radians(lat2-lat1)/2),2) + cos(radians(lat1))*cos(radians(lat2))*power(sin(radians(lon2-lon1)/2),2)
  ));
$$;

-- from supabase/migrations/20261008120000_fraud_compliance_notifications.sql
CREATE OR REPLACE FUNCTION public.hrms_record_fraud_signal(
  p_user_id uuid, p_event_type text, p_severity text, p_score integer, p_reasons jsonb,
  p_latitude double precision DEFAULT NULL, p_longitude double precision DEFAULT NULL,
  p_accuracy double precision DEFAULT NULL, p_mocked boolean DEFAULT false
) RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_day date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_id uuid;
  v_name text;
  v_attendance uuid;
BEGIN
  SELECT id INTO v_attendance FROM public.attendance_logs WHERE user_id = p_user_id AND date = v_day
  ORDER BY created_at LIMIT 1;
  INSERT INTO public.attendance_fraud_events (
    attendance_id, user_id, event_type, score, severity, reasons, latitude, longitude, accuracy_m, is_mocked, event_day
  ) VALUES (
    v_attendance, p_user_id, p_event_type, greatest(0, least(100, p_score)), p_severity, coalesce(p_reasons, '[]'::jsonb),
    p_latitude, p_longitude, p_accuracy, coalesce(p_mocked, false), v_day
  ) ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN RETURN NULL; END IF;  -- already recorded today

  IF p_severity = 'SUSPICIOUS' THEN
    SELECT name INTO v_name FROM public.profiles WHERE id = p_user_id;
    PERFORM public.hrms_notify_line_and_hr(p_user_id,
      'Suspicious attendance activity',
      coalesce(v_name, 'An employee') || ': ' || coalesce(p_reasons->>0, p_event_type),
      'fraud_suspicious', 'fraud:' || v_id, '/HRMS/admin/suspicious-attendance',
      jsonb_build_object('fraudEventId', v_id, 'userId', p_user_id));
  END IF;
  RETURN v_id;
EXCEPTION WHEN others THEN
  RAISE WARNING 'fraud signal skipped: %', SQLERRM;
  RETURN NULL;
END;
$$;

-- from scripts/add_attendance_fraud_detection.sql
CREATE OR REPLACE FUNCTION rpc_analyze_attendance_fraud(
  p_user_id UUID,
  p_attendance_id UUID,
  p_event_type TEXT,
  p_latitude DOUBLE PRECISION,
  p_longitude DOUBLE PRECISION,
  p_accuracy_m DOUBLE PRECISION DEFAULT NULL,
  p_is_mocked BOOLEAN DEFAULT FALSE,
  p_developer_mode BOOLEAN DEFAULT FALSE,
  p_ip_latitude DOUBLE PRECISION DEFAULT NULL,
  p_ip_longitude DOUBLE PRECISION DEFAULT NULL,
  p_office_distance_m INTEGER DEFAULT NULL
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  v_score INTEGER := 0;
  v_reasons JSONB := '[]'::JSONB;
  v_severity TEXT;
  v_ip_distance INTEGER;
  v_same_location_count INTEGER := 0;
  v_boundary_count INTEGER := 0;
  v_previous RECORD;
  v_travel_distance INTEGER;
  v_elapsed_seconds NUMERIC;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() <> p_user_id THEN
    RETURN jsonb_build_object('success', FALSE, 'error', 'FORBIDDEN');
  END IF;

  IF COALESCE(p_is_mocked, FALSE) THEN
    v_score := v_score + 70;
    v_reasons := v_reasons || jsonb_build_array('Mock location reported by device');
  END IF;
  IF COALESCE(p_developer_mode, FALSE) THEN
    v_score := v_score + 20;
    v_reasons := v_reasons || jsonb_build_array('Developer mode enabled');
  END IF;
  IF p_accuracy_m IS NULL OR p_accuracy_m > 100 THEN
    v_score := v_score + 25;
    v_reasons := v_reasons || jsonb_build_array('Poor GPS accuracy');
  END IF;

  IF p_ip_latitude IS NOT NULL AND p_ip_longitude IS NOT NULL THEN
    v_ip_distance := ROUND(6371000 * 2 * ASIN(SQRT(
      POWER(SIN(RADIANS(p_ip_latitude - p_latitude) / 2), 2) +
      COS(RADIANS(p_latitude)) * COS(RADIANS(p_ip_latitude)) *
      POWER(SIN(RADIANS(p_ip_longitude - p_longitude) / 2), 2)
    )))::INTEGER;
    IF v_ip_distance > 50000 THEN
      v_score := v_score + 25;
      v_reasons := v_reasons || jsonb_build_array('VPN/IP location differs from GPS by over 50km');
    END IF;
  END IF;

  SELECT COUNT(*) INTO v_same_location_count
  FROM attendance_fraud_events f
  WHERE f.user_id <> p_user_id
    AND f.created_at > NOW() - INTERVAL '15 minutes'
    AND ROUND(6371000 * 2 * ASIN(SQRT(
      POWER(SIN(RADIANS(f.latitude - p_latitude) / 2), 2) +
      COS(RADIANS(p_latitude)) * COS(RADIANS(f.latitude)) *
      POWER(SIN(RADIANS(f.longitude - p_longitude) / 2), 2)
    ))) <= 5;
  IF v_same_location_count >= 2 THEN
    v_score := v_score + 30;
    v_reasons := v_reasons || jsonb_build_array('Same GPS coordinates used by multiple employees');
  END IF;

  SELECT latitude, longitude, recorded_at INTO v_previous
  FROM location_tracking
  WHERE user_id = p_user_id AND latitude IS NOT NULL AND longitude IS NOT NULL
  ORDER BY recorded_at DESC LIMIT 1;
  IF FOUND THEN
    v_elapsed_seconds := EXTRACT(EPOCH FROM (NOW() - v_previous.recorded_at));
    v_travel_distance := ROUND(6371000 * 2 * ASIN(SQRT(
      POWER(SIN(RADIANS(v_previous.latitude - p_latitude) / 2), 2) +
      COS(RADIANS(p_latitude)) * COS(RADIANS(v_previous.latitude)) *
      POWER(SIN(RADIANS(v_previous.longitude - p_longitude) / 2), 2)
    )))::INTEGER;
    IF v_elapsed_seconds BETWEEN 1 AND 120 AND v_travel_distance > 20000 THEN
      v_score := v_score + 45;
      v_reasons := v_reasons || jsonb_build_array('Impossible travel: over 20km within two minutes');
    END IF;
  END IF;

  IF p_office_distance_m BETWEEN 90 AND 110 THEN
    SELECT COUNT(*) INTO v_boundary_count FROM attendance_fraud_events
    WHERE user_id = p_user_id
      AND created_at > NOW() - INTERVAL '30 days'
      AND reasons ? 'Boundary-range check-in';
    v_reasons := v_reasons || jsonb_build_array('Boundary-range check-in');
    IF v_boundary_count >= 2 THEN v_score := v_score + 15; END IF;
  END IF;

  v_score := LEAST(v_score, 100);
  v_severity := CASE WHEN v_score <= 30 THEN 'NORMAL' WHEN v_score <= 60 THEN 'WARNING' ELSE 'SUSPICIOUS' END;

  INSERT INTO attendance_fraud_events (
    attendance_id, user_id, event_type, score, severity, reasons,
    latitude, longitude, accuracy_m, is_mocked, developer_mode,
    ip_latitude, ip_longitude, ip_gps_distance_m
  ) VALUES (
    p_attendance_id, p_user_id, UPPER(p_event_type), v_score, v_severity, v_reasons,
    p_latitude, p_longitude, p_accuracy_m, p_is_mocked, p_developer_mode,
    p_ip_latitude, p_ip_longitude, v_ip_distance
  );

  IF p_attendance_id IS NOT NULL THEN
    UPDATE attendance_logs SET fraud_score = v_score, fraud_severity = v_severity, fraud_reasons = v_reasons
    WHERE id = p_attendance_id;
  END IF;
  RETURN jsonb_build_object('success', TRUE, 'score', v_score, 'severity', v_severity, 'reasons', v_reasons);
END;
$$;

-- from supabase/migrations/20260918030000_log_failed_checkins_rpc.sql
create or replace function public.rpc_attendance_checkin_v2(
  p_office_id uuid,
  p_location jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_office public.offices%rowtype;
  v_lat double precision;
  v_lon double precision;
  v_accuracy double precision;
  v_radius double precision;
  v_distance double precision;
  v_captured_at timestamptz;
  v_result jsonb;
  v_checkin_time timestamptz;
begin
  if v_uid is null then
    return jsonb_build_object(
      'success', false, 'error', 'AUTHENTICATION_REQUIRED',
      'message', 'A valid session is required.'
    );
  end if;

  if not exists (select 1 from public.profiles where id = v_uid and is_active = true) then
    return jsonb_build_object(
      'success', false, 'error', 'USER_INACTIVE',
      'message', 'Your account is inactive.'
    );
  end if;

  select * into v_office
  from public.offices
  where id = p_office_id and coalesce(is_active, true);
  
  if not found or v_office.latitude is null or v_office.longitude is null then
    return jsonb_build_object(
      'success', false, 'error', 'OFFICE_LOCATION_UNAVAILABLE',
      'message', 'The requested office location is unavailable or inactive.'
    );
  end if;

  v_radius := coalesce(
    v_office.allowed_radius_meters,
    v_office.attendance_radius
  );
  if v_radius is null or v_radius < 10 or v_radius > 1000 then
    return jsonb_build_object(
      'success', false, 'error', 'OFFICE_RADIUS_NOT_CONFIGURED',
      'message', 'Attendance radius is not configured for this office. Contact HR.'
    );
  end if;

  begin
    v_lat := (p_location->>'latitude')::double precision;
    v_lon := (p_location->>'longitude')::double precision;
    v_accuracy := greatest(0, (p_location->>'accuracy')::double precision);
    v_captured_at := coalesce(
      (p_location->>'capturedAt')::timestamptz,
      (p_location->>'captured_at')::timestamptz,
      now()
    );
  exception when others then
    return jsonb_build_object(
      'success', false, 'error', 'INVALID_GPS',
      'message', 'A valid precise GPS reading is required.'
    );
  end;

  v_distance := public.field_visit_distance_metres(
    v_office.latitude, v_office.longitude, v_lat, v_lon
  );

  if v_lat = 0 or v_lon = 0 or
     v_lat not between -90 and 90 or v_lon not between -180 and 180 or
     v_accuracy > 100 or
     lower(coalesce(p_location->>'mocked', 'false')) = 'true' or
     v_captured_at < now() - interval '60 seconds' or
     v_captured_at > now() + interval '10 seconds' then
     
    insert into public.checkin_attempts (
      user_id, attempted_at, latitude, longitude, nearest_office_name, nearest_office_distance_m, status, failure_reason
    ) values (
      v_uid, now(), v_lat, v_lon, v_office.name, v_distance, 'failed', 'The GPS reading is inaccurate, stale, invalid, or mocked.'
    );
    
    return jsonb_build_object(
      'success', false, 'error', 'GPS_NOT_TRUSTED',
      'message', 'The GPS reading is inaccurate, stale, invalid, or mocked.'
    );
  end if;

  if v_distance + v_accuracy > v_radius then
    
    insert into public.checkin_attempts (
      user_id, attempted_at, latitude, longitude, nearest_office_name, nearest_office_distance_m, status, failure_reason
    ) values (
      v_uid, now(), v_lat, v_lon, v_office.name, v_distance, 'geo_fence_blocked', format('Distance (%s m) exceeds radius (%s m)', ceil(v_distance + v_accuracy), ceil(v_radius))
    );
    
    return jsonb_build_object(
      'success', false, 'error', 'OUTSIDE_OFFICE_RADIUS',
      'message', format(
        'Your verified distance (%s m including GPS uncertainty) exceeds the %s m office radius.',
        ceil(v_distance + v_accuracy), ceil(v_radius)
      ),
      'distance_metres', v_distance,
      'accuracy_metres', v_accuracy,
      'allowed_radius_metres', v_radius
    );
  end if;

  v_result := public.rpc_attendance_checkin(
    v_uid, p_office_id, p_location, v_distance, 'APP'
  );
  if coalesce((v_result->>'success')::boolean, false) then
    select checkin_time
    into v_checkin_time
    from public.attendance_logs
    where user_id = v_uid
      and date = (now() at time zone 'Asia/Kolkata')::date
      and checkin_time is not null
    order by checkin_time
    limit 1;
    v_result := v_result || jsonb_build_object(
      'checkin_time', v_checkin_time,
      'server_now', now()
    );
  end if;
  return v_result;
end;
$$;

-- from supabase/migrations/20260813000000_fix_lucknow_checkin_loading_issue.sql
create or replace function public.rpc_attendance_checkin_v3(
  p_office_id uuid,
  p_location  jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid             uuid := auth.uid();
  v_result          jsonb;
  v_attendance      public.attendance_logs%rowtype;
  v_profile         public.profiles%rowtype;
  v_office          public.offices%rowtype;
  v_site            public.predefined_sites%rowtype;
  v_site_distance   double precision;
  v_office_distance double precision;
  v_lat             double precision;
  v_lon             double precision;
  v_accuracy        double precision;
  v_visit_id        uuid;
  v_today           date := (now() at time zone 'Asia/Kolkata')::date;
  v_retry           integer := 0;
begin
  -- Step 1: run core v2 check-in (idempotent, advisory-locked)
  v_result := public.rpc_attendance_checkin_v2(p_office_id, p_location);
  if not coalesce((v_result->>'success')::boolean, false) then
    return v_result;
  end if;

  v_lat      := (p_location->>'latitude')::double precision;
  v_lon      := (p_location->>'longitude')::double precision;
  v_accuracy := greatest(0, coalesce((p_location->>'accuracy')::double precision, 0));

  -- Step 2: safe fetch with retry (replaces SELECT INTO STRICT which threw
  -- an exception when the row was not yet visible under DB load — this was
  -- the primary cause of the Lucknow "4-5 attempts" loading loop).
  loop
    select * into v_attendance
    from public.attendance_logs
    where user_id        = v_uid
      and date           = v_today
      and checkin_time is not null
    order by checkin_time
    limit 1;

    exit when found;
    v_retry := v_retry + 1;
    exit when v_retry >= 3;
    perform pg_sleep(0.1);  -- 100ms back-off per retry
  end loop;

  -- If still not found after retries, return success without side-effects.
  -- The check-in itself already committed — do not fail the whole call.
  if not found then
    return v_result || jsonb_build_object(
      'side_effects_committed',      false,
      'side_effects_skipped_reason', 'attendance_row_not_yet_visible'
    );
  end if;

  -- Step 3: fetch profile and office (non-strict, bail gracefully)
  select * into v_profile from public.profiles where id = v_uid;
  if not found then
    return v_result || jsonb_build_object(
      'attendance_id',          v_attendance.id,
      'side_effects_committed', true
    );
  end if;

  select * into v_office from public.offices where id = p_office_id;
  if not found then
    return v_result || jsonb_build_object(
      'attendance_id',          v_attendance.id,
      'side_effects_committed', true
    );
  end if;

  -- Step 4: manager distance warning (non-fatal, wrapped in exception block)
  begin
    v_office_distance := public.field_visit_distance_metres(
      v_office.latitude, v_office.longitude, v_lat, v_lon
    );
    if v_profile.reports_to is not null and v_office_distance > 50 then
      insert into public.notifications(user_id, title, message, type)
      select
        v_profile.reports_to,
        'Attendance Warning',
        format('%s checked in %s m away from %s',
          v_profile.name, round(v_office_distance), v_office.name),
        'attendance_warning'
      where not exists (
        select 1 from public.notifications n
        where n.user_id  = v_profile.reports_to
          and n.type     = 'attendance_warning'
          and n.message  = format('%s checked in %s m away from %s',
                             v_profile.name, round(v_office_distance), v_office.name)
          and n.created_at >= (
            date_trunc('day', now() at time zone 'Asia/Kolkata')
            at time zone 'Asia/Kolkata'
          )
      );
    end if;
  exception when others then null;
  end;

  -- Step 5: auto-detect nearest predefined site (non-fatal)
  begin
    select site.* into v_site
    from public.predefined_sites site
    where site.is_active
      and site.latitude         is not null
      and site.longitude        is not null
      and site.checkin_radius_m is not null
      and public.field_visit_distance_metres(
            site.latitude, site.longitude, v_lat, v_lon
          ) + v_accuracy <= site.checkin_radius_m
    order by public.field_visit_distance_metres(
               site.latitude, site.longitude, v_lat, v_lon
             ), site.id
    limit 1;

    if found then
      v_site_distance := public.field_visit_distance_metres(
        v_site.latitude, v_site.longitude, v_lat, v_lon
      );
      insert into public.field_visits(
        user_id, predefined_site_id, visit_type, location_name,
        location_address, destination_coords, checkin_radius_m, project_name,
        notes, checkin_time, checkin_location, status, date, journey_status,
        auto_attendance_id
      ) values (
        v_uid, v_site.id, 'site', v_site.site_label,
        v_site.address,
        jsonb_build_object('latitude', v_site.latitude, 'longitude', v_site.longitude),
        v_site.checkin_radius_m, v_site.project_name,
        format('Auto-detected during attendance check-in · %s m from site',
               round(v_site_distance)),
        v_attendance.checkin_time,
        jsonb_build_object(
          'latitude',    v_lat,
          'longitude',   v_lon,
          'accuracy',    v_accuracy,
          'captured_at', coalesce(p_location->>'capturedAt', p_location->>'captured_at'),
          'provider',    'attendance-checkin'
        ),
        'CHECKED_IN', v_attendance.date, 'SITE_CHECKED_IN', v_attendance.id
      )
      on conflict (auto_attendance_id) where auto_attendance_id is not null
      do update set auto_attendance_id = excluded.auto_attendance_id
      returning id into v_visit_id;
    end if;
  exception when others then null;
  end;

  return v_result || jsonb_build_object(
    'attendance_id',                  v_attendance.id,
    'automatic_site_visit_id',        v_visit_id,
    'automatic_site_name',
      case when v_visit_id is null then null else v_site.site_label end,
    'automatic_site_distance_metres', v_site_distance,
    'side_effects_committed',         true
  );
end;
$$;

-- from supabase/migrations/20260907020000_fix_biometric_assignment_and_smartoffice_proxy.sql
CREATE OR REPLACE FUNCTION public.rpc_sync_biometric_punches(p_punches jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Kolkata')::date;
  v_inserted_logs integer := 0;
  v_updated_attendance integer := 0;
BEGIN
  IF p_punches IS NULL OR jsonb_array_length(p_punches) = 0 THEN
    RETURN jsonb_build_object('success', true, 'updated', 0, 'message', 'No punches provided');
  END IF;

  -- A. Insert raw punches into smartoffice_device_logs
  INSERT INTO public.smartoffice_device_logs (
    employee_code,
    log_datetime,
    serial_number,
    punch_direction,
    temperature
  )
  SELECT
    trim(r->>'EmployeeCode'),
    trim(r->>'LogDate'),
    coalesce(r->>'SerialNumber', ''),
    coalesce(r->>'PunchDirection', ''),
    coalesce((r->>'Temperature')::numeric, 0)
  FROM jsonb_array_elements(p_punches) AS r
  WHERE nullif(trim(r->>'EmployeeCode'), '') IS NOT NULL
    AND nullif(trim(r->>'LogDate'), '') IS NOT NULL
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_inserted_logs = ROW_COUNT;

  -- B. Link unlinked logs to active employee profiles
  UPDATE public.smartoffice_device_logs dl
  SET user_id = p.id
  FROM public.profiles p
  WHERE (
      lower(trim(p.smartoffice_employee_code)) = lower(trim(dl.employee_code))
      OR lower(trim(p.employee_number)) = lower(trim(dl.employee_code))
    )
    AND p.is_active = true
    AND dl.user_id IS NULL;

  -- C. Upsert attendance_logs for today with earliest-in-time check-in resolution
  WITH parsed_punches AS (
    SELECT
      dl.user_id,
      p.office_id,
      v_today AS att_date,
      (trim(dl.log_datetime) || '+05:30')::timestamptz AS punch_ts
    FROM public.smartoffice_device_logs dl
    JOIN public.profiles p ON p.id = dl.user_id
    WHERE dl.user_id IS NOT NULL
      AND length(trim(dl.log_datetime)) >= 10
      AND substring(trim(dl.log_datetime) from 1 for 10) = v_today::text
  ),
  daily_group AS (
    SELECT
      user_id,
      office_id,
      att_date,
      min(punch_ts) AS first_punch,
      max(punch_ts) AS last_punch,
      count(*)::int AS punch_cnt
    FROM parsed_punches
    GROUP BY user_id, office_id, att_date
  )
  INSERT INTO public.attendance_logs(
    user_id,
    office_id,
    date,
    checkin_time,
    checkin_source,
    checkout_time,
    checkout_source,
    status,
    attendance_status,
    day_status,
    attendance_type,
    smartoffice_imported,
    biometric_first_punch,
    biometric_last_punch,
    biometric_punch_count,
    work_hours,
    updated_at
  )
  SELECT
    g.user_id,
    g.office_id,
    g.att_date,
    g.first_punch,
    'BIOMETRIC',
    NULL,
    NULL,
    'CHECKED_IN',
    'PRESENT',
    'P',
    'BIOMETRIC',
    true,
    g.first_punch,
    g.last_punch,
    g.punch_cnt,
    NULL,
    now()
  FROM daily_group g
  ON CONFLICT (user_id, date) DO UPDATE
  SET
    -- Check-in time: Earliest punch wins across Biometric & App!
    checkin_time = CASE
      WHEN attendance_logs.checkin_time IS NULL THEN EXCLUDED.checkin_time
      WHEN EXCLUDED.checkin_time < attendance_logs.checkin_time THEN EXCLUDED.checkin_time
      ELSE attendance_logs.checkin_time
    END,
    -- Check-in source: Reflects whichever source occurred earlier:
    checkin_source = CASE
      WHEN attendance_logs.checkin_time IS NULL THEN 'BIOMETRIC'
      WHEN EXCLUDED.checkin_time < attendance_logs.checkin_time THEN 'BIOMETRIC'
      ELSE coalesce(attendance_logs.checkin_source, 'BIOMETRIC')
    END,
    smartoffice_imported = true,
    biometric_first_punch = EXCLUDED.biometric_first_punch,
    biometric_last_punch = EXCLUDED.biometric_last_punch,
    biometric_punch_count = EXCLUDED.biometric_punch_count,
    attendance_status = 'PRESENT',
    day_status = 'P',
    status = CASE
      WHEN attendance_logs.checkout_time IS NULL THEN 'CHECKED_IN'
      ELSE attendance_logs.status
    END,
    updated_at = now();

  GET DIAGNOSTICS v_updated_attendance = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'inserted_raw_punches', v_inserted_logs,
    'updated_attendance_count', v_updated_attendance,
    'date', v_today
  );
END;
$$;

-- from supabase/migrations/20260806010000_canonical_attendance_calendar_tracking.sql
create or replace function public.require_protected_checkout_audit()
returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if new.date=(now() at time zone 'Asia/Kolkata')::date and new.checkout_time is not null
   and new.checkout_time is distinct from old.checkout_time
   and current_setting('app.authorized_attendance_correction',true)<>'REGULARIZATION'
   and not exists(select 1 from public.attendance_audit_logs audit where audit.attendance_id=new.id
    and audit.new_checkout_at=new.checkout_time and ((audit.action in ('CHECKOUT_MANUAL','CHECKOUT_EARLY') and audit.source='APP')
      or (audit.action='CHECKOUT_AUTO' and audit.source='SYSTEM'))) then
  raise exception 'CHECKOUT_REQUIRES_HRMS_OR_AUTHORIZED_CORRECTION';
 end if;
 return null;
end $$;

CREATE CONSTRAINT TRIGGER require_protected_checkout_audit_trigger
  AFTER UPDATE OF checkout_time ON public.attendance_logs DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION public.require_protected_checkout_audit();
